def transform(grid):
    h, w = len(grid), len(grid[0])
    # Separator rows and columns are the uniform lines.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if all(grid[r][c] == grid[0][c] for r in range(h))]

    # In these puzzles, separators share a color; the marks have a distinct color.
    sep_color = grid[sep_rows[0]][0] if sep_rows else grid[0][sep_cols[0]]
    mark_color = next(
        color for row in grid for color in row
        if color != sep_color and color not in (grid[0][0],)
    )
    background = next(color for row in grid for color in row
                      if color != sep_color and color != mark_color)

    row_bounds = [-1] + sep_rows + [h]
    col_bounds = [-1] + sep_cols + [w]
    out = []
    for ri in range(len(row_bounds) - 1):
        row = []
        for ci in range(len(col_bounds) - 1):
            count = sum(
                grid[r][c] == mark_color
                for r in range(row_bounds[ri] + 1, row_bounds[ri + 1])
                for c in range(col_bounds[ci] + 1, col_bounds[ci + 1])
            )
            row.append(1 if count > 1 else background)
        out.append(row)
    return out
